// Create your EventMap interface here

// Create the TypedEventEmitter class here

class TypedEventEmitter<EventMap extends Record<string, any>> {
  private listeners: { [K in keyof EventMap]?: ((data: EventMap[K]) => void)[] } = {};

  on<K extends keyof EventMap>(event: K, callback: (data: EventMap[K]) => void): void {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event]!.push(callback);
  }

  off<K extends keyof EventMap>(event: K, callback: (data: EventMap[K]) => void): void {
    const callbacks = this.listeners[event];
    if (callbacks) {
      const index = callbacks.indexOf(callback);
      if (index > -1) {
        callbacks.splice(index, 1);
      }
    }
  }

  emit<K extends keyof EventMap>(event: K, data: EventMap[K]): void {
    const callbacks = this.listeners[event];
    if (callbacks) {
      callbacks.forEach(callback => callback(data));
    }
  }
}

// Create the UserEvents type definition here
interface UserEvents {
  login: { username: string; timestamp: Date };
  logout: { username: string };
}

// Instantiate the typed event emitter here
const userEmitter = new TypedEventEmitter<UserEvents>();

// Register event listeners with type checking
userEmitter.on('login', (data) => {
  console.log(`User ${data.username} logged in at ${data.timestamp}`);
});

userEmitter.on('logout', (data) => {
  console.log(`User ${data.username} logged out`);
});

